SELECT 7 resolution,count(*) FILTER(WHERE abs((fraction_hard+fraction_wet+fraction_urban+fraction_forest+fraction_excavation+fraction_waste+fraction_shrub+fraction_orchard+fraction_square+fraction_grass+fraction_unused+fraction_other_open+unknown_fraction)-1)>1e-8) bad_partition,count(*) FILTER(WHERE NOT ST_IsValid(geom)) invalid_geom,count(*) FILTER(WHERE iop<>iop_offroad OR iop IS NULL) bad_score, sum(area_m2*(iop-.15*fraction_urban))/sum(area_m2) urban_minus080_sensitivity, sum(area_m2*(iop+.15*fraction_urban))/sum(area_m2) urban_minus050_sensitivity FROM grid.iop_v2_r7;
